"""Build the active 10A1 bank from the two uploaded books only.
Usage: python scripts/build-grade10-advanced-textbook-bank.py /path/to/part1.pdf /path/to/part2.pdf
Requires PyMuPDF and SymPy. Original diagrams are clipped, never redrawn.
"""
from pathlib import Path
import hashlib, json, sys, math
import fitz
import sympy as S
ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'public/data/exam-banks/10a1-term1';(OUT/'assets').mkdir(parents=True,exist_ok=True)
books={i:fitz.open(sys.argv[i]) for i in [1,2]}
assert len(books[1])==60 and len(books[2])==164
parts={str(i):dict(file_name=Path(sys.argv[i]).name,sha256=hashlib.sha256(Path(sys.argv[i]).read_bytes()).hexdigest(),printed_start=627 if i==1 else 57,pdf_pages=len(books[i])) for i in [1,2]}
old=json.loads((ROOT/'content-imports/legacy-10a1-parallel-bank/index.json').read_text())
outcomes=[{k:v for k,v in o.items() if k not in ['question_ids','question_count','download']} for o in old['learning_outcomes']]
questions=[];assets={}
def source(page,ex,mcq=True):
 part=1 if page>=627 else 2
 return dict(book_part=part,book_sha256=parts[str(part)]['sha256'],printed_page=page,pdf_page=page-parts[str(part)]['printed_start']+1,exercise=str(ex),adaptation='mcq' if mcq else 'transcription')
def crop(id,page,box,ex):
 src=source(page,ex,False);p=books[src['book_part']][src['pdf_page']-1];rect=fitz.Rect(box[0]*p.rect.width,box[1]*p.rect.height,box[2]*p.rect.width,box[3]*p.rect.height)
 pix=p.get_pixmap(matrix=fitz.Matrix(3,3),clip=rect);pix.save(OUT/f'assets/{id}.png')
 assets[id]=dict(src=f'assets/{id}.png',width=pix.width,height=pix.height,alt_text=f'Original textbook diagram, Reveal p. {page}, exercise {ex}.',source=src,crop_box=list(box));return id

def mc(lo,page,ex,instruction,expr,correct,wrong,why,image=None):
 i=sum(q['learning_outcome_id']==f'LO{lo:02}' for q in questions)+1
 values=[correct,*wrong];assert len(values)==4
 texts=[S.latex(v) if isinstance(v,S.Basic) else v for v in values]
 if lo==5:texts=[r'\begin{gathered}'+v.replace('=',r'=\\')+r'\end{gathered}' for v in texts]
 if lo==18:texts=[r'\begin{gathered}'+v.replace(',\\ ',r'\\')+r'\end{gathered}' for v in texts]
 assert len(set(texts))==4,(lo,ex)
 if all(isinstance(v,S.Basic) for v in values):assert all(S.simplify(values[a]-values[b])!=0 for a in range(4) for b in range(a))
 order=list(range(4));shift=(lo+i)%4;order=order[shift:]+order[:shift]
 options=[dict(id='ABCD'[n],text=texts[k][5:] if texts[k].startswith('TEXT:') else texts[k],**({} if texts[k].startswith('TEXT:') else dict(math_latex=texts[k]))) for n,k in enumerate(order)]
 answer=options[order.index(0)]
 questions.append(dict(id=f'G10A-BOOK-Q{lo:02}-MCQ-{i:02}',learning_outcome_id=f'LO{lo:02}',type='mcq',display_number=f'{lo}.{i}',instruction=instruction,stem=instruction+(' '+expr if expr else ''),math_latex=expr,options=options,marks=None,answer=dict(correct_option_id=answer['id'],correct_option_text=answer['text'],explanation=why),diagram_asset_ids=[image] if image else [],source=source(page,ex)))
def pt(prompt,answer,marks=10,latex='',height=40):return dict(id='a',prompt=prompt,marks=marks,math_latex='',workspace=dict(height_mm=height),answer=dict(model_answer_and_marking=answer,math_latex=latex))
def fr(lo,page,ex,instruction,expr,parts,image=None):
 i=sum(q['learning_outcome_id']==f'LO{lo:02}' for q in questions)+1
 assert sum(p['marks'] for p in parts)==10
 for k,p in enumerate(parts):p['id']=chr(97+k)
 questions.append(dict(id=f'G10A-BOOK-Q{lo:02}-FRQ-{i:02}',learning_outcome_id=f'LO{lo:02}',type='frq',display_number=f'{lo}.{i}',instruction=instruction,stem=instruction+(' '+expr if expr else ''),math_latex=expr,parts=parts,marks=10,diagram_asset_ids=[image] if image else [],source=source(page,ex,False)))
def geo(lo,page,ex,prompt,ans,bad,why,box):mc(lo,page,ex,prompt,'',ans,bad,why,crop(f'q{lo}_{ex}',page,box,ex))
def number(lo,page,ex,prompt,value,why,image=None):
 ans=S.Rational(str(value));mc(lo,page,ex,prompt,'',ans,[ans+1,ans-1,ans+5],why,image)
def text(v):return 'TEXT:'+v
x,y,a,b,c,d,f,g,h,k,m,n,p,q,r,t,u,v,w,z=S.symbols('x y a b c d f g h k m n p q r t u v w z')
# Algebra: all selected numeric expressions are literal book exercises.
for ex,expr,ans in [(10,'-y^3+3y-3y^2+2',-y**3-3*y**2+3*y+2),(13,r'\frac12x-3x^4+7',-3*x**4+x/2+7)]:
 lc=-1 if ex==10 else -3;mc(1,635,ex,'Write in standard form and identify the leading coefficient.',expr,rf'{S.latex(ans)},\quad {lc}',[rf'{S.latex(-ans)},\quad {-lc}',rf'{S.latex(ans)},\quad {-lc}',rf'{S.latex(ans)},\quad 2'],'Order terms by decreasing exponent; the leading coefficient is the coefficient of the first term.')
for ex,e,expr in [(22,(2*h**2-5*h)+(7*h-3*h**2),'(2h^2-5h)+(7h-3h^2)'),(26,(2*x+3*x**2)-(7-8*x**2),'(2x+3x^2)-(7-8x^2)')]:
 ans=S.expand(e);mc(1,635,ex,'Find the sum or difference.',expr,ans,[ans+1,-ans,ans-x],'Distribute any subtraction sign, then combine like powers.')
for ex,e in enumerate([(3*c-5)*(c+3),(g+10)*(2*g-5),(6*a+5)*(5*a+3),(4*x+1)*(6*x+3)],1):
 ans=S.expand(e);var=sorted(e.free_symbols,key=str)[0];mc(2,649,ex,'Find the product.',S.latex(e),ans,[ans+var,ans-var,ans+1],'Multiply every term by both terms of the other binomial and combine the middle products.')
for ex,e in [(11,f*g-5*g+4*f-20),(13,h*S.Symbol('j')-2*h+5*S.Symbol('j')-10),(14,x*y-2*x-2+y),(20,v*p+12*v+8*p+96)]:
 ans=S.factor(e);mc(3,665,ex,'Factor completely using the Distributive Property.',S.latex(e),ans,[-ans,2*ans,ans.subs(sorted(e.free_symbols,key=str)[0],sorted(e.free_symbols,key=str)[0]+1)],'Group terms to extract the same binomial factor from both groups.')
for ex,e in enumerate([x**2+17*x+42,y**2-17*y+72,a**2+8*a-48,n**2-2*n-35],1):
 ans=S.factor(e);mc(4,671,ex,'Factor using integers.',S.latex(e),ans,[-ans,2*ans,ans.subs(sorted(e.free_symbols,key=str)[0],sorted(e.free_symbols,key=str)[0]+1)],'Use two integer factors of the constant whose sum is the middle coefficient.')
