(3,r'(A,B,C,D,E)=(90,90,128,74,158)^\circ',[r'(A,B,C,D,E)=(90,90,140,80,170)^\circ',r'(A,B,C,D,E)=(90,90,124,72,154)^\circ',r'(A,B,C,D,E)=(90,90,158,74,128)^\circ'],'Pentagon sum=540. 180+(2x−20)+x+(2x+10)=540, giving x=74.',(.14,.355,.46,.49)),
