(10,'(a,b)=(2,3)',['(a,b)=(3,2)','(a,b)=(13,6)','(a,b)=(4,3)'],'Opposite sides are equal: a+15=3a+11, 3b+5=b+11.',(.50,.12,.78,.235)),
(11,r'(x,y)=(58,\frac{127}{2})',['(x,y)=(58,29)','(x,y)=(60,60)','(x,y)=(53,58)'],'Adjacent angles: (x−5)+(2x+11)=180, so x=58. Opposite angles: 2y=2x+11=127.',(.05,.318,.30,.425)),
