for ex,value,why,box in [(11,3,'Corresponding edges satisfy (x+1)/8=(3x+1)/20. Cross multiply to get x=3.',(.05,.505,.46,.59)),(12,2,'(3x−1)/4=(8x−1)/12 gives 36x−12=32x−4, so x=2.',(.47,.505,.88,.59)),(13,5,'The large-to-small scale factor is 3/2. Hence (2x+2)/(x+3)=3/2 and x=5.',(.05,.585,.46,.71)),(14,7,'Corresponding side ratios give (x+5)/15=4/5, so x+5=12 and x=7.',(.47,.585,.89,.71))]:geo(10,128,ex,'Each pair of polygons is similar. Find x.',S.Integer(value),[S.Integer(value+1),S.Integer(value-1),S.Integer(value+3)],why,box)
